import{z as A,x as n,o,c as p,q as s,j as t,D as E,d as i,s as l,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"VFIO","description":"","frontmatter":{"title":"VFIO","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/vfio.md","filePath":"cs/vfio.md","lastUpdated":1791063341000}'),M={name:"cs/vfio.md"};function d(c,a,D,m,I,f){const r=n("Mermaid");return o(),p("div",null,[a[2]||(a[2]=s('<h1 id="vfio" tabindex="-1">VFIO <a class="header-anchor" href="#vfio" aria-label="Permalink to &quot;VFIO&quot;">​</a></h1><div class="epigraph"><p>VFIO 把 IOMMU 组交给用户进程：QEMU mmap 设备 BAR、映射客户内存给 DMA，实现安全设备直通。</p><footer>—— 据 Linux vfio 文档；[DMA/IOMMU](/cs/dma-coherence) 与 [DPDK](/cs/dpdk-kernel-bypass) 为先修</footer></div><p><a href="/cs/sriov-passthrough">SR-IOV</a> 要有框架绑设备。<a href="/cs/chardev-ioctl">ioctl</a> 再出现：<code>/dev/vfio</code>。缺口是 <strong>VFIO</strong>：组、容器、与设备隔离。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>IOMMU 组必须整组给一个用户，否则 DMA 别名。VFIO：用户拿组 → 设 DMA map → mmap MMIO。缺口：no-IOMMU 模式危险；与 <a href="/cs/secure-boot">secure boot</a> 模块签名。本课不把每个 PCI quirk 列出。</p><p><span class="marginnote">vfio-pci 替换宿主驱动。对象是安全用户 DMA，不仅是虚拟化。</span></p><p><span class="marginnote">术语翻译：VFIO 组就是用「IOMMU 把物理上会被一起 DMA 的设备打包成组、整组交给一个用户」的手段来做「用户态也能安全地直接驱动设备」的事——组是隔离的最小单位，拆不开是因为硬件桥可能让设备互相伪装 DMA。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>解绑宿主驱动 → 绑 vfio-pci → QEMU 打开组 → 运行。对照 DPDK：同一 VFIO，用途旁路而非客户。对照 <a href="/cs/chardev-ioctl">chardev</a>：vfio 就是一类 cdev。对照 KSM：客户页仍可被宿主合并，直通 DMA 要钉页。</p>',9)),(o(),t(B,null,{default:E(()=>[l(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20GRP%5B%22IOMMU%20%E7%BB%84%22%5D%20--%3E%20U%5B%22%E7%94%A8%E6%88%B7%20VFIO%22%5D%0A%20%20U%20--%3E%20MAP%5B%22DMA%20%E6%98%A0%E5%B0%84%E5%AE%A2%E6%88%B7%E5%86%85%E5%AD%98%22%5D%0A%20%20U%20--%3E%20BAR%5B%22mmap%20%E8%AE%BE%E5%A4%87%20BAR%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>VFIO 把「设备用户态驱动」做成有 IOMMU 的一等公民，KVM 直通与 DPDK 共用。没有组隔离就没有安全直通。不要写成驱动编写教程。与 <a href="/cs/memcg">memcg</a>：钉页会计。</p><p>错误映射等于客户写宿主。</p><p><span class="marginnote">为什么重要：VFIO 容器里的 DMA 映射表就是客户地址到宿主物理地址的翻译凭证——映射错了、或把没钉住的宿主页交给了设备，设备的下一次 DMA 就会写到宿主内核的数据上。这就是「错误映射等于客户写宿主」的机制来源，也是直通前必须钉页的原因。</span></p><p>实现上：组内任一设备给客户，组内其它也必须解绑宿主驱动。no-iommu 模式等于信任用户 DMA 整机。mmap BAR 后客户 MMIO 不再 exit。 读法上只引用<a href="/cs/sriov-passthrough">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「虚拟化与隔离进阶 / Hypervisor」课序里，对象是 <strong>VFIO</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 mdev/vGPU 的全部。不保证所有桥接芯片组可拆组。下一课中断虚拟化。</p><p>版本字段会变，课序钉的是机制对象「VFIO」，不是某一主线内核的结构体名。 后课默认：直通经 VFIO+IOMMU 组。客户中断如何少 exit，下一课 posted interrupt。</p>',10)),(o(),t(B,null,{default:E(()=>[l(r,{id:"mermaid-70",class:"mermaid",graph:"flowchart%20TD%0A%20%20BIND%5B%22%E8%A7%A3%E7%BB%91%E5%AE%BF%E4%B8%BB%E9%A9%B1%E5%8A%A8%2C%20%E7%BB%91%20vfio-pci%22%5D%20--%3E%20GRP%5B%22%E6%89%93%E5%BC%80%20IOMMU%20%E7%BB%84%E6%95%B4%E7%BB%84%22%5D%0A%20%20GRP%20--%3E%20PIN%5B%22%E9%92%89%E4%BD%8F%E5%AE%A2%E6%88%B7%E9%A1%B5%22%5D%0A%20%20PIN%20--%3E%20MAP%5B%22VFIO%20ioctl%20%E5%BB%BA%20DMA%20%E6%98%A0%E5%B0%84%22%5D%0A%20%20MAP%20--%3E%20MMIO%5B%22mmap%20%E8%AE%BE%E5%A4%87%20BAR%22%5D%0A%20%20MMIO%20--%3E%20RUN%5B%22%E8%AE%BE%E5%A4%87%20DMA%20%E7%9B%B4%E8%BE%BE%E5%AE%A2%E6%88%B7%E5%86%85%E5%AD%98%22%5D%0A%20%20RUN%20--%3E%20EXIT%7B%22%E6%99%AE%E9%80%9A%E8%AE%BF%E5%AD%98%E8%A6%81%E9%99%B7%E5%85%A5%E5%90%97%3F%22%7D%0A%20%20EXIT%20--%20%22MMIO%20%E4%B8%8E%20DMA%22%20--%3E%20NOEXIT%5B%22%E4%B8%8D%E7%BB%8F%E5%AE%BF%E4%B8%BB%E5%86%85%E6%A0%B8%22%5D%0A%20%20EXIT%20--%20%22%E9%85%8D%E7%BD%AE%E7%B1%BB%E6%93%8D%E4%BD%9C%22%20--%3E%20KEXIT%5B%22%E5%B0%91%E6%95%B0%E4%BB%8D%E8%B5%B0%E5%86%85%E6%A0%B8%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者容易以为「用户态拿到设备」等于绕过了 IOMMU，实际上 VFIO 的安全性恰恰建立在 IOMMU 之上——设备只能 DMA 到容器里登记过的页面；真正绕过一切保护的是 no-iommu 模式，那是明确放弃隔离的危险开关。")],-1)),a[5]||(a[5]=e("h2",{id:"小结",tabindex:"-1"},[i("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[6]||(a[6]=e("ul",null,[e("li",null,"VFIO 将 IOMMU 组授予用户做 DMA/MMIO。"),e("li",null,"是 KVM 直通与用户态驱动的共同底座。"),e("li",null,"中断虚拟化是下一课。"),e("li",null,"出处：Linux vfio；IOMMU；KVM。")],-1))])}const h=A(M,[["render",d]]);export{u as __pageData,h as default};
